/// <summary>
/// PaffH 29.09.25
/// </summary>
public void initValue()
{
    super();

    this.Active = NoYes::Yes;
}

/// <summary>
/// PaffH 30.09.25
/// </summary>
/// <param name = "_fieldId">FieldId</param>
public void modifiedField(FieldId _fieldId)
{
    super(_fieldId);

    switch (_fieldId)
    {
        case (fieldNum(NDXBVEMailRequestInstaller, DirPartyTableManual)) :
            NDXBVEmailRequestRoleIdentificationContract::construct(this).checkIdentification();
            break;
    }
}

/// <summary>
/// PaffH 29.09.25
/// insert Plumber (manual)
/// </summary>
/// <param name = "_guiId">NDXGUID</param>
/// <returns>NDXBVEMailRequestInstaller</returns>
public static NDXBVEMailRequestInstaller insertManual(NDXGUID _guiId)
{
    NDXBVEMailRequestInstaller nDXBVEMailRequestPlumber;
    select firstonly nDXBVEMailRequestPlumber order by IdentifierLine desc where nDXBVEMailRequestPlumber.IdentifierGUID == _guiId;
    Line identifierLineNew = nDXBVEMailRequestPlumber.IdentifierLine + 1;

    nDXBVEMailRequestPlumber.clear();
    nDXBVEMailRequestPlumber.initValue();
    nDXBVEMailRequestPlumber.IdentifierGUID = _guiId;
    nDXBVEMailRequestPlumber.IdentifierLine = identifierLineNew;
    nDXBVEMailRequestPlumber.Manual = NoYes::Yes;
    NDXBVEmailRequestRoleIdentificationContract::construct(nDXBVEMailRequestPlumber).checkIdentification();
    if (nDXBVEMailRequestPlumber.validateWrite())
    {
        nDXBVEMailRequestPlumber.insert();
    }
    return nDXBVEMailRequestPlumber;
}

/// <summary>
/// PaffH 29.09.25
/// delete manual record
/// </summary>
/// <returns>deleted ?</returns>
public boolean deleteManual()
{
    if (this.Manual == NoYes::Yes)
    {
        if (this.validateDelete())
        {
            ttsbegin;
            this.delete();
            ttscommit;
            return true;
        }
    }
    else if (this.Active)
    {
        this.Active = NoYes::No;
        if (this.validateWrite())
        {
            ttsbegin;
            this.update();
            ttscommit;
        }
    }
    return false;
}

/// <summary>
/// PaffH 29.09.25
/// </summary>
/// <returns>dirPartyTable</returns>
private DirPartyTable getDirPartyTable()
{
    DirPartyTable dirPartyTable;
    if (this.DirPartyTableManual)
    {
        dirPartyTable = DirPartyTable::findRec(this.DirPartyTableManual);
    }
    else if (this.ProspectProspectId)
    {
        dirPartyTable = DirPartyTable::findByNum(this.ProspectProspectId);
    }
    return DirPartyTable;
}

/// <summary>
/// PaffH 29.09.25
/// </summary>
/// <returns>Name 1</returns>
[SysClientCacheDataMethod(true)]
public display NDXLogisticsLocationName1 dispName1()
{
    DirPartyTable dirPartyTable = this.getDirPartyTable();

    if (dirPartyTable)
    {
        return LogisticsPostalAddress::findByLocation(dirPartyTable.PrimaryAddressLocation).NDXLogisticsLocationName1;
    }
    else
    {
        return this.Name1;
    }
}

